import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote: base premiums", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a sword → base premium 100 G (+10 G first insurance + 5 G fee = 115 G)");
  it.todo("an amulet → base premium 60 G (+6 G first insurance + 5 G fee = 71 G)");
  it.todo("a staff → base premium 80 G (+8 G first insurance + 5 G fee = 93 G)");
  it.todo("a potion → base premium 40 G (+4 G first insurance + 5 G fee = 49 G)");
  it.todo("a single rune → base premium 25 G (component)");
  it.todo("a single moonstone → base premium 25 G (component)");
});

describe("MHPCO Claim Office — quote: building block of 3 alike components", () => {
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
});

describe("MHPCO Claim Office — quote: premium modifiers", () => {
  it.todo("cursed sword adds 50 G risk surcharge (50 % of the item's base premium)");
  it.todo("sword with enchantment 5 adds 30 G high-enchantment surcharge");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges");
  it.todo("customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO gets no loyalty discount");
  it.todo("every item in a quote carries the 10 % first insurance surcharge");
  it.todo("the customer's second quote gets the 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added at the very end of every premium");
});

describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the cursed item's base) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers (loyalty, follow-up) apply to the sum of all item base premiums");
});

describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
});

describe("MHPCO Claim Office — quote: integration examples", () => {
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
});

describe("MHPCO Claim Office — claim: standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
});

describe("MHPCO Claim Office — claim: special clauses", () => {
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
});

describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G (based on the unmodified insurance value)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("sword (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G; second payout 600 G, remaining cap 0 G");
});

describe("MHPCO Claim Office — claim: multiple items of the same type", () => {
  it.todo("two insured swords both damaged → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than the policy insures → the claim is rejected");
});

describe("MHPCO Claim Office — errors", () => {
  it.todo("a quote with an unknown item type (e.g. broomstick) → error, no results");
  it.todo("a claim damaging an item that is not part of the policy (amulet when only a sword is insured) → error");
  it.todo("a claim damaging an item with an unknown type → error");
  it.todo("a claim with a damage entry of amount -200 → error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("exits with a non-zero status and writes an error description to stderr on an invalid scenario");
});

