// The MHPCO rounds premiums in its own favour.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => item.type === "rune");

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const policyBasePremium = (items: Item[]): number =>
  formsComponentBlock(items)
    ? COMPONENT_BLOCK_PREMIUM
    : sumOfItemBasePremiums(items);

const quotePremium = (items: Item[]): number =>
  roundedInMHPCOsFavour(
    withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE,
  );

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

