const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = ["rune", "moonstone"];

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const formsComponentBlock = (group: Item[]): boolean =>
  group.length === COMPONENT_BLOCK_SIZE &&
  COMPONENT_TYPES.includes(group[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const groupBasePremium = (group: Item[]): number =>
  formsComponentBlock(group)
    ? COMPONENT_BLOCK_PREMIUM
    : sumOfItemBasePremiums(group);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);

