});

describe("MHPCO Claim Office — claim: standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
