export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: Incident };

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_RATE = 0.1;

// Deliberately additive: `policyBase * 1.1` is not float-equivalent
// (100 * 1.1 === 110.00000000000001), and the final rounding-up turns that
// stray ulp into a whole extra gold piece. Do not "simplify".
const withFirstInsuranceSurcharge = (policyBase: number): number =>
  policyBase + policyBase * FIRST_INSURANCE_RATE;

// The MHPCO rounds premiums in its own favour.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

// A group is every item of one single type, so a group is always non-empty
// and homogeneous — the block rule below relies on both.
interface TypeGroup {
  type: string;
  items: Item[];
}

const groupByType = (items: Item[]): TypeGroup[] =>
  [
    ...items.reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    ),
  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));

const formsComponentBlock = (group: TypeGroup): boolean =>
  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const groupBasePremium = (group: TypeGroup): number =>
  formsComponentBlock(group)
    ? COMPONENT_BLOCK_PREMIUM
    : sumOfItemBasePremiums(group.items);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);

const CURSE_SURCHARGE_RATE = 0.5;

// Item-specific modifiers are charged on the affected item's own base premium,
// unlike the policy-wide modifiers which apply to the sum of all of them.
const curseSurcharge = (item: Item): number =>
  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;

const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_RATE = 0.3;

// An unenchanted item may leave `enchantment` unset; absent means level 0.
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const highEnchantmentSurcharge = (item: Item): number =>
  isHighlyEnchanted(item) ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE : 0;

const itemSurcharge = (item: Item): number =>
  curseSurcharge(item) + highEnchantmentSurcharge(item);

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const quotePremium = (items: Item[]): number =>
  roundedInMHPCOsFavour(
    withFirstInsuranceSurcharge(policyBasePremium(items)) +
      totalItemSurcharges(items) +
      PROCESSING_FEE,
  );

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

