export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: Incident };

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_RATE = 0.1;

// Kept as a separate additive term rather than folded into a `policyBase * 1.1`
// factor: that is not float-equivalent (100 * 1.1 === 110.00000000000001), and
// the final rounding-up turns the stray ulp into a whole extra gold piece.
// Do not "simplify".
const firstInsuranceSurcharge = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_RATE;

// The MHPCO rounds premiums in its own favour.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

// A group is every item of one single type, so a group is always non-empty
// and homogeneous — the block rule below relies on both.
interface TypeGroup {
  type: string;
  items: Item[];
}

const groupByType = (items: Item[]): TypeGroup[] =>
  [
    ...items.reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    ),
  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));

const formsComponentBlock = (group: TypeGroup): boolean =>
  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const groupBasePremium = (group: TypeGroup): number =>
  formsComponentBlock(group)
    ? COMPONENT_BLOCK_PREMIUM
    : sumOfItemBasePremiums(group.items);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);

const CURSE_SURCHARGE_RATE = 0.5;

// Item-specific modifiers are charged on the affected item's own base premium,
// unlike the policy-wide modifiers which apply to the sum of all of them.
const curseSurcharge = (item: Item): number =>
  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;

const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_RATE = 0.3;

// An unenchanted item may leave `enchantment` unset; absent means level 0.
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const highEnchantmentSurcharge = (item: Item): number =>
  isHighlyEnchanted(item) ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE : 0;

const itemSurcharge = (item: Item): number =>
  curseSurcharge(item) + highEnchantmentSurcharge(item);

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS
    ? policyBase * LOYALTY_DISCOUNT_RATE
    : 0;

// Policy-wide modifiers are charged on the sum of all item base premiums,
// unlike the item-specific ones above. Each returns a signed adjustment:
// surcharges positive, discounts negative.
const policyModifiers = (policyBase: number, customer: Customer): number =>
  firstInsuranceSurcharge(policyBase) - loyaltyDiscount(customer, policyBase);

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = policyBasePremium(items);
  return roundedInMHPCOsFavour(
    policyBase +
      policyModifiers(policyBase, customer) +
      totalItemSurcharges(items) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, customer) };
  }
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote: base premiums", () => {
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("a sword → base premium 100 G (+10 G first insurance + 5 G fee = 115 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 0, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("an amulet → base premium 60 G (+6 G first insurance + 5 G fee = 71 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("a staff → base premium 80 G (+8 G first insurance + 5 G fee = 93 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("a potion → base premium 40 G (+4 G first insurance + 5 G fee = 49 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });
  it("runes are components at 25 G each → 2 runes = 50 G base premium", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    // 2 × 25 G base = 50 G, +5 G first insurance, +5 G fee
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("moonstones are components at 25 G each → 2 moonstones = 50 G base premium", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }, { type: "moonstone" }] }],
    });

    // 2 × 25 G base = 50 G, +5 G first insurance, +5 G fee
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
});

describe("MHPCO Claim Office — quote: building block of 3 alike components", () => {
  // "2 runes → 50 G" is covered by the component-price test above.
  it("3 runes → 60 G base premium (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    // block base 60 G, +6 G first insurance, +5 G fee
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    // 4 × 25 G = 100 G base, +10 G first insurance, +5 G fee
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
      ],
    });

    // 7 × 25 G = 175 G base (no block), +17.5 G first insurance, +5 G fee = 197.5 → 198
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    // 3 × 25 G = 75 G base (no block — types differ), +7.5 G, +5 G fee = 87.5 → 88
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });

    // two blocks of 60 G = 120 G base, +12 G first insurance, +5 G fee
    expect(result).toEqual({ results: [{ premium: 137 }] });
  });
});

describe("MHPCO Claim Office — quote: premium modifiers", () => {
  it("cursed sword adds 50 G risk surcharge (50 % of the item's base premium)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
        },
      ],
    });

    // 100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee
    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword with enchantment 5 adds 30 G high-enchantment surcharge", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 5, cursed: false }],
        },
      ],
    });

    // 100 G base + 30 G high enchantment + 10 G first insurance + 5 G fee
    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it("sword with enchantment 4 gets no high-enchantment surcharge", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 4, cursed: false }],
        },
      ],
    });

    // 100 G base + 10 G first insurance + 5 G fee — no surcharge below level 5
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("cursed sword with enchantment 5 gets both surcharges", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 5, cursed: true }],
        },
      ],
    });

    // 100 G base + 50 G curse + 30 G high enchantment + 10 G first insurance + 5 G fee
    expect(result).toEqual({ results: [{ premium: 195 }] });
  });
  it("customer with exactly 2 years with MHPCO gets the 20 % loyalty discount", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 2 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 1, cursed: false }],
        },
      ],
    });

    // 100 G base − 20 G loyalty + 10 G first insurance + 5 G fee
    expect(result).toEqual({ results: [{ premium: 95 }] });
  });
  it.todo("customer with 1 year with MHPCO gets no loyalty discount");
  it.todo("every item in a quote carries the 10 % first insurance surcharge");
  it.todo("the customer's second quote gets the 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added at the very end of every premium");
});

describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the cursed item's base) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers (loyalty, follow-up) apply to the sum of all item base premiums");
});

describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
});

describe("MHPCO Claim Office — quote: integration examples", () => {
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
});

describe("MHPCO Claim Office — claim: standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
});

describe("MHPCO Claim Office — claim: special clauses", () => {
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
});

describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G (based on the unmodified insurance value)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("sword (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G; second payout 600 G, remaining cap 0 G");
});

describe("MHPCO Claim Office — claim: multiple items of the same type", () => {
  it.todo("two insured swords both damaged → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than the policy insures → the claim is rejected");
});

describe("MHPCO Claim Office — errors", () => {
  it.todo("a quote with an unknown item type (e.g. broomstick) → error, no results");
  it.todo("a claim damaging an item that is not part of the policy (amulet when only a sword is insured) → error");
  it.todo("a claim damaging an item with an unknown type → error");
  it.todo("a claim with a damage entry of amount -200 → error");
});

