const DEDUCTIBLE = 100;
const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};
const CAP_MULTIPLE = 2;

// The MHPCO rounds payouts in its own favour too — the other way.
const payoutRoundedInMHPCOsFavour = (payout: number): number =>
  Math.floor(payout);

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);

const capOf = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLE;

const reimbursement = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimPayout = (incident: Incident): number =>
  payoutRoundedInMHPCOsFavour(
    incident.damages.reduce((total, damage) => total + reimbursement(damage), 0),
  );

const insuredItemsOf = (steps: Step[], policy: number): Item[] => {
  const policyStep = steps[policy];
  if (policyStep.op !== "quote") {
    throw new Error(`step ${policy} is not a quote`);
  }
  return policyStep.items;
};

const runStep = (step: Step, context: QuoteContext, steps: Step[]): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, context) };
  }
  const insuredItems = insuredItemsOf(steps, step.policy);
  const payout = claimPayout(step.incident);
  return { payout, remainingCap: capOf(insuredItems) - payout };
};

const countQuotes = (steps: Step[]): number =>
  steps.filter((step) => step.op === "quote").length;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    runStep(
      step,
      {
        customer: scenario.customer,
        precedingQuotes: countQuotes(scenario.steps.slice(0, index)),
      },
      scenario.steps,
    ),
  ),
});

