  unclaimedItems: Item[],
  damage: Damage,
): { item: Item; remainingItems: Item[] } => {
  const index = unclaimedItems.findIndex(({ type }) => type === damage.itemType);
  if (index === -1) {
    throw new Error(`${damage.itemType} is not insured by this policy`);
  }
