250	// A claim's `policy` is an index into the scenario's own steps, so it can miss
251	// in two ways: point past the end, or point at another claim. Both are the same
252	// mistake — a policy reference that no policy answers — and both are reported
253	// here rather than left to surface as a bare property access on `undefined`.
254	// (`steps[policy]` is typed `Step`, but only because `noUncheckedIndexedAccess`
255	// is off; at runtime an out-of-range index really is `undefined`.)
256	const insuredItemsOf = (steps: Step[], policy: number): Item[] => {
257	  const policyStep = steps.at(policy);
